from pathlib import Path
import hashlib,json,math,re,tempfile,importlib.util
REPO=Path('/home/octadim/MyProjects/Multi_User_RAG_Assist_System');OUT=REPO/'harness/common/testing/evidence/2026-10-19-preserve-approved-visual-design'
spec=importlib.util.spec_from_file_location('v',REPO/'harness/common/testing/evidence/2026-10-19-instruction-form-selection/validate.py');v=importlib.util.module_from_spec(spec);spec.loader.exec_module(v)
v.NAME='comm-preserve-visual-design';v.CANDIDATE=REPO/'harness/common/inbox/2026-10-19-preserve-approved-visual-design/candidate'/v.NAME

def tokens(s):return math.ceil(len(s.encode('utf-16-le'))/8)
def record(p,root):
 data=p.read_bytes();return dict(path=str(p.relative_to(root)),sha256=hashlib.sha256(data).hexdigest(),bytes=len(data),static_tokens=tokens(data.decode()))
contexts=[]
for mode in ('common','both'):
 for phase in ('baseline','candidate'):
  with tempfile.TemporaryDirectory(prefix='visual-context-') as d:
   root=Path(d);v.prepare(root,mode,phase)
   paths=[root/'AGENTS.md',root/'harness/common/START.md',root/'harness/project/START.md',*sorted(p for p in (root/'.claude/rules').rglob('*.md') if p.name!='README.human.md'),root/'harness/common/INDEX.md',root/'harness/project/INDEX.md']
   guards=[record(p,root) for p in paths]
   metadata=[]
   for p in sorted((root/'.agents/skills').glob('*/SKILL.md')):
    front=p.read_text().split('---',2)[1];name=re.search(r'^name: (.*)$',front,re.M).group(1);desc=re.search(r'^description: (.*)$',front,re.M).group(1)
    metadata.append(dict(name=name,description=desc,static_tokens=tokens(name)+tokens(desc)))
   resources=[record(p,root) for p in sorted((root/'harness/common/skills').rglob('*.md')) if p.name!='README.human.md']
   contexts.append(dict(mode=mode,phase=phase,startup=guards,metadata=metadata,startup_tokens=sum(p['static_tokens'] for p in guards),metadata_tokens=sum(p['static_tokens'] for p in metadata),all_available_skill_resources=resources,all_available_tokens=sum(p['static_tokens'] for p in resources)))
expected={str(p.relative_to(REPO)):p.read_text() for p in (REPO/'.claude/rules').glob('*.md') if p.name!='README.human.md'}
body=(v.CANDIDATE/'SKILL.md').read_text();old=json.loads((OUT/'original-inputs.json').read_text())
oldbody=next(value['text'] for path,value in old.items() if path.endswith('SKILL.md'))
native=[]
for p in sorted([*OUT.glob('*-native-*.json'),*OUT.glob('v2-native-render-*.json')]):
 raw=json.loads(p.read_text());commands=[];images=[];usage=[]
 for line in raw['stdout'].splitlines():
  try:event=json.loads(line)
  except ValueError:continue
  item=event.get('item',{})
  if event.get('type')=='item.completed' and item.get('type')=='command_execution':commands.append(item)
  if item.get('tool')=='view_image' or item.get('name')=='view_image':images.append(item)
  if event.get('type')=='turn.completed':usage.append(event.get('usage'))
 missing=[name for name,txt in expected.items() if not any(txt in c.get('aggregated_output','') and c.get('exit_code')==0 for c in commands)]
 reads=[dict(command=c['command'],exit_code=c.get('exit_code'),bytes=len(c.get('aggregated_output','').encode()),static_tokens=tokens(c.get('aggregated_output',''))) for c in commands if 'cat ' in c.get('command','') or 'sed -n ' in c.get('command','')]
 used=any(body in c.get('aggregated_output','') or oldbody in c.get('aggregated_output','') for c in commands)
 before=raw.get('before',{});after=raw.get('after',{})
 native.append(dict(file=p.name,completed=raw['completed'],exit_code=raw['exit_code'],complete_rule_reading=not missing,missing_rules=missing,skill_read=used,read_receipts=reads,actual_read_output_static_tokens=sum(x['static_tokens'] for x in reads),usage=usage,changes=sorted(k for k in before.keys()|after.keys() if before.get(k)!=after.get(k))))
with (OUT/'v2-context-and-native-receipts.json').open('x') as f:json.dump(dict(method='ceil(UTF-16 code units /4); static estimate, not billed tokens',startup_cap=None,contexts=contexts,native=native),f,ensure_ascii=False,indent=2)
for x in contexts:print(x['mode'],x['phase'],x['startup_tokens'],x['metadata_tokens'],x['all_available_tokens'])
for x in native:print(x['file'],x['completed'],x['skill_read'],x['complete_rule_reading'],x['missing_rules'],x['changes'])
